/// <summary>
/// Reversé depuis lapis::CNC_CW_ClientGetCharacters (WorldServer).
/// Champs C++ originaux : byte, short, int, std::string, short, short, short, short, short, byte, byte, ushort, short, byte, ushort, ushort, short, short, short, short, short, short, short, short, long
/// </summary>
public sealed class CNC_CW_ClientGetCharacters : NetCommand
{
    public override int Opcode => 38;
    public override string Name => "CNC_CW_ClientGetCharacters";

    /// <summary>Élément d'aperçu wire = 28 octets :
    /// [u16 loc][u16 item_id][s16 x8][i64].
    /// Natif observé : s8 = [0,-1,-1,-1,-1,-1,-1,0], l = 0.</summary>
    public sealed class PreviewItem
    {
        public ushort Loc;
        public ushort ItemId;
        public short[] S = new short[8];
        public long L;

        /// <summary>Item d'équipement par défaut (embedded_id1..6 = -1).</summary>
        public static PreviewItem Equipped(int loc, int itemId)
        {
            var it = new PreviewItem { Loc = (ushort)loc, ItemId = (ushort)itemId };
            for (var i = 1; i <= 6; i++) it.S[i] = -1;
            return it;
        }
    }

    /// <summary>Entrée personnage — layout natif vérifié par capture MITM :
    /// i32 id, string name, s16 class(+0x12), s16 flag(+0x14), s16 race(+0x10),
    /// s16 node(+0x0e), s16 level(+0x0c), u8 (+0x7d), blob apparence 32o (+0x24),
    /// u8 (+0x7c), u16 nbNoeudsPreview (+0x58), puis map&lt;u16,vec&lt;item&gt;&gt;.</summary>
    public sealed class Entry
    {
        public int Id;
        public string Name = "";
        public short ClassId;
        public short Feature;  // +0x14 : class_lv — désasm PGCharacterDBO
                               // GetData("class_lv") → this+0x14. Le client
                               // l'affiche comme niveau de classe ("Lv0" si 0).
        public short RaceId;   // +0x10
        public short NodeId;   // +0x0e
        public short Level;    // +0x0c
        public byte B1;        // +0x7d — observé 0
        public byte[] Appearance = new byte[32]; // +0x24 — blob client renvoyé tel quel
        public byte B2;        // +0x7c — observé 0
        /// <summary>map&lt;u16 conteneur, Liste&lt;PreviewItem&gt;&gt; — aperçu équipement.</summary>
        public List<KeyValuePair<ushort, List<PreviewItem>>> Preview { get; } = new();
    }

    /// <summary>Section native : 0, 1 (personnages), 2 — un message par section.</summary>
    public short Header;
    public List<Entry> Characters { get; } = new();

    public override void Serialize(OutBinStream stream)
    {
        stream.WriteByte((byte)Characters.Count);
        stream.WriteShort(Header);
        foreach (var c in Characters)
        {
            stream.WriteInt(c.Id);
            stream.WriteString(c.Name);
            stream.WriteShort(c.ClassId);
            stream.WriteShort(c.Feature);
            stream.WriteShort(c.RaceId);
            stream.WriteShort(c.NodeId);
            stream.WriteShort(c.Level);
            stream.WriteByte(c.B1);
            stream.WriteBytes(c.Appearance, 32);
            stream.WriteByte(c.B2);
            stream.WriteShort((short)c.Preview.Count);
            foreach (var kv in c.Preview)
            {
                stream.WriteShort((short)kv.Key);
                stream.WriteByte((byte)kv.Value.Count);
                foreach (var it in kv.Value)
                {
                    stream.WriteShort((short)it.Loc);
                    stream.WriteShort((short)it.ItemId);
                    for (var i = 0; i < 8; i++) stream.WriteShort(it.S[i]);
                    stream.WriteLong(it.L);
                }
            }
        }
    }

    public override void Deserialize(InBinStream stream)
    {
        var count = stream.ReadByte();
        Header = stream.ReadShort();
        for (var i = 0; i < count; i++)
        {
            var c = new Entry
            {
                Id = stream.ReadInt(),
                Name = stream.ReadString(),
                ClassId = stream.ReadShort(),
                Feature = stream.ReadShort(),
                RaceId = stream.ReadShort(),
                NodeId = stream.ReadShort(),
                Level = stream.ReadShort(),
                B1 = stream.ReadByte(),
                Appearance = stream.ReadBytes(32),
                B2 = stream.ReadByte(),
            };
            Characters.Add(c);
        }
    }
}

